def shear_up_left(grid, color=None):
    """Shift every cell left by (bottom_row - row): vertical strokes become down-right diagonals; cells passing column 0 are dropped."""
    h = len(grid); w = len(grid[0])
    rows = [i for i in range(h) if any(v != 0 for v in grid[i])]
    if not rows:
        return [row[:] for row in grid]
    rb = max(rows)
    out = [[0]*w for _ in range(h)]
    for i in rows:
        s = rb - i
        for j, v in enumerate(grid[i]):
            if v != 0 and j - s >= 0:
                out[i][j - s] = v
    return out

